  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `revenue_distributions_bill_item_id_foreign` (`bill_item_id`),
  CONSTRAINT `revenue_distributions_bill_item_id_foreign` FOREIGN KEY (`bill_item_id`) REFERENCES `bill_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8098 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
